-- Reference data required in every environment, so it lives in a migration rather than
-- supabase/seed.sql (db push promotes migrations only). All inserts are idempotent, so
-- `db reset` and re-pushes are safe.
--
-- The weather_codes block is generated by `python3 -m app.weather_codes` — regenerate it
-- there rather than editing by hand; app/weather_codes.py is the single source of truth.

on conflict (code) do update set description = excluded.description;

-- Coordinates verified against Open-Meteo's geocoding API; all America/Denver.
on conflict (name) do update set
  latitude = excluded.latitude,
  longitude = excluded.longitude;
